let activation;
export function enableOffline(){if(activation)return activation;activation=(async()=>{if(!('serviceWorker'in navigator))throw Error('Bu tarayıcı çevrimdışı derlemeyi desteklemiyor.');const timeout=new Promise((_,reject)=>setTimeout(()=>reject(Error('Önbellek başlatılamadı; bağlantıyı kontrol edip yeniden deneyin.')),30000));await Promise.race([(async()=>{await navigator.serviceWorker.register(new URL('./offline-worker.js',import.meta.url),{type:'module',scope:'./',updateViaCache:'none'});await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(resolve=>navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true}));})(),timeout]);return true;})().catch(error=>{activation=null;throw error;});return activation;}
export async function cacheRequest(action,data={},onProgress=()=>{}){await enableOffline();return new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>{channel.port1.close();reject(Error('Önbellek işlemi zaman aşımı.'));},action==='warm'?600000:30000);channel.port1.onmessage=({data})=>{if(data.progress){onProgress(data.progress);return;}clearTimeout(timer);channel.port1.close();data.ok?resolve(data.result):reject(Error(data.error));};navigator.serviceWorker.controller.postMessage({action,...data},[channel.port2]);});}
export async function showOfflinePanel({showDialog,closeDialog}){
 showDialog('Derleyici önbelleği',`<div class="cache-panel"><p>GCC 0.2.0 · 55 MB · dosyalar bu cihazda</p><div id="cache-status">Kontrol ediliyor…</div><progress id="cache-progress" max="550" value="0" style="width:100%"></progress><div class="dialog-actions"><button id="cache-warm">Hazırla</button><button id="cache-cancel" disabled>İptal</button><button id="cache-clear">Önbelleği temizle</button></div><label><input id="cache-offline" type="checkbox" disabled> Çevrimdışı · yalnız önbellek</label><div id="cache-error" role="status"></div></div>`);
 const $=id=>document.getElementById(id),status=$('cache-status'),error=$('cache-error'),warm=$('cache-warm'),cancel=$('cache-cancel'),clear=$('cache-clear'),offline=$('cache-offline'),progress=$('cache-progress');
 const refresh=async()=>{const s=await cacheRequest('status');status.textContent=`${s.count}/${s.total} · ${(s.bytes/1048576).toFixed(1)} MB · ${s.ready&&s.shellReady?'Hazır':'Eksik'}`;progress.max=s.total;progress.value=s.count;offline.checked=s.offline;offline.disabled=!s.ready||!s.shellReady;warm.disabled=s.offline;return s;};
 warm.onclick=async()=>{error.textContent='';warm.disabled=true;clear.disabled=true;cancel.disabled=false;offline.disabled=true;try{await cacheRequest('warm',{},p=>{status.textContent=`${p.count}/${p.total} dosya`;progress.value=p.count;});}catch(e){error.textContent=e.message;}finally{cancel.disabled=true;clear.disabled=false;try{await refresh();}catch(e){error.textContent=e.message;}}};
 cancel.onclick=()=>cacheRequest('cancel').catch(e=>error.textContent=e.message);
 clear.onclick=async()=>{try{await cacheRequest('clear');await refresh();}catch(e){error.textContent=e.message;}};
 offline.onchange=async()=>{try{await cacheRequest('mode',{offline:offline.checked});await refresh();}catch(e){error.textContent=e.message;await refresh();}};
 try{await refresh();}catch(e){error.textContent=e.message;status.textContent='Kullanılamıyor';warm.disabled=true;clear.disabled=true;}
}
